  el.textContent='LIVE SCORE DIAGNOSTICS\n'+(ac.on?'AUTO: ON':'AUTO: OFF')+'   FACE: '+c.face+' / '+c.prof.style+'\nSCENE: '+(ac.directScene||c.scene)+'   SECTION: '+(ac.currentSection||'—')+'\nREASON: '+(ac.directReason||'—')+'\n'+pending+'\nBPM: '+Math.round((window.autoSynth&&window.autoSynth.getBPM?window.autoSynth.getBPM():c.prof.bpm))+'   LAYERS: '+ac.layers+'   DRUMS: '+(ac.drums?'IN':'OUT')+'\nVOICES: '+live+' / '+budget+'   MANUAL DUCK: '+(Date.now()<(ac.manualUntil||0)?'YES':'NO')+'\nPEAK: '+db(t.peak||0)+' dB   RMS: '+db(t.rms||0)+' dB\nBUS REDUCTION: '+(t.busReduction||0).toFixed(2)+' dB\nSAFETY REDUCTION: '+(t.safetyReduction||0).toFixed(2)+' dB   CLIP: '+(t.clipActive?'ROUNDING':'CLEAR')+'\nENV: '+c.pType+' / '+c.mode+'   ALT: '+Math.round(c.alt)+'   SPD: '+c.spd.toFixed(2)+'\nAUDITION MAX: '+db(a.maxPeak)+' dB   MAX VOICES: '+a.maxVoices+'   CLIP SAMPLES: '+a.clipFrames+'/'+a.samples+'\nALT+D toggles this panel';
