  const note=ac.melody&&ac.melody[phraseStep];if(note){const lift=(section==='CREST'||section==='CLIMAX'||section==='ASCENT')?1.06:(section==='BREATH'?.80:1);_acPlay('melody',_acReflect(root+note.off,c.lo,c.hi),1,note.vel*lift,note.hold,3,c);}
  if(ac.layers>=2){const ans=ac.counter&&ac.counter[phraseStep];if(ans&&section!=='BREATH')_acPlay('counter',_acReflect(root+ans.off+2,c.lo,c.hi),2,ans.vel,ans.hold,2,c);}
