window.autoCompose=function(on,len){const ac=_acState();if(typeof len==='number')ac.len=len;ac.on=(on===undefined)?!ac.on:!!on;if(ac.on){ac.tick=0;ac.absBar=0;ac.phraseNo=0;ac.seed=Math.random()*1000+1;ac.directCtxKey=null;ac.pending=null;ac.transitionGain=.72;ac.lastClimaxBar=-999;window.resetComposerAuditionStats();_acGenerate(true);try{if(window.autoSynth&&window.autoSynth.ensureRunning)window.autoSynth.ensureRunning();}catch(e){}}else _acStopAll();_acSyncControls();_acDiagnosticsTick(true);return ac.on?('AUTO ORCHESTRA '+ac.len+' — LAYERS '+ac.layers+(ac.drums?' + DRUMS':'')):'AUTO ORCHESTRA OFF';};
