        'uniform sampler2D tDiffuse;',
        'uniform vec2 uSunUV;',
        'uniform float uActive;',
        'uniform vec3 uColor;',
        'uniform float uAspect;',
        'varying vec2 vUv;',
        'void main(){',
        '  vec4 src = texture2D(tDiffuse, vUv);',
        '  if (uActive < 0.01) { gl_FragColor = src; return; }',
        '  // Radial-blur sample toward the sun, accumulating bright pixels into rays.',
