    const arm = Math.floor(Math.random() * ARMS);
    const t = Math.pow(Math.random(), 0.6);
    const rad = BULGE_R + t * (R - BULGE_R);
    const swirl = Math.log(rad / BULGE_R + 1.0) * 2.4;
    const th = (arm / ARMS) * Math.PI * 2 + swirl + (Math.random() - 0.5) * 0.4;
    const dx = Math.cos(th) * rad;
