        uSunDir: { value: new THREE.Vector3(0.45, 0.75, 0.3).normalize() },
        uPlanetClass: { value: 0.0 },   // 0 GAS 1 OCEAN 2 MAGMA 3 TERRAN 4 ICE 5 ARID
