            dlo = lonM-1.22; dla = latM-0.14; dk += 0.75*exp(-dlo*dlo*6.0 - dla*dla*9.0);  // Syrtis Major
            dlo = lonM;      dla = latM+0.10; dk += 0.55*exp(-dlo*dlo*4.0 - dla*dla*10.0); // Meridiani/Erythraeum
            dlo = lonM+0.52; dla = latM-0.78; dk += 0.50*exp(-dlo*dlo*5.0 - dla*dla*7.0);  // Mare Acidalium (N)
            dlo = lonM-2.60; dla = latM+0.35; dk += 0.45*exp(-dlo*dlo*3.0 - dla*dla*8.0);  // Mare Cimmerium (SE)
