// Refresh impostor positions/colors around the player\u0027s current cell. Cheap:
// span*span sprites (default 24). Skips the current cell (real system there).
// vox327: NEIGHBOR SUNS, THE RIGHT WAY (user directive; user has no console).
// History: fix123 sprite impostors -> vox127 pushed systems to 260000u and the
// far plane clipped them dark -> vox294 retired them as blobs -> vox326
// un-clipped the sprites. Resolution: the SPRITE layer is retired for good
// (window._GALAXY_IMPOSTORS defaults false), and neighboring systems' suns
// render instead as a Points layer using the same tech as the skybox stars:
// constant pixel size (sizeAttenuation off) with the soft round sprite map,
// so they read as crisp bright stars at ANY distance and geometrically
// cannot become the vox294 blobs. True cell positions, true parallax,
// far-plane clamped. A persistent NEAR SUNS toggle lives in the FX panel.
let _neighborStars = null, _neighborStarsGeom = null;
let _neighborStarsCellX = null, _neighborStarsCellZ = null, _neighborStarsGal = null;
window._NEIGHBOR_SUNS = (function () { try { return localStorage.getItem('l99_near_suns') !== '0'; } catch (e) { return true; } })();
window._NEIGHBOR_STAR_PX = 8;   // constant on-screen size (skybox near stars are 2.5); the one dial
function _buildNeighborStars(){buildStars207();}
 function _updateNeighborStars(){/* frame207 updates the catalog once after camera movement. */}
 function updateGalaxyImpostors() {
  if (!_galaxyImpostors) return;
  try { _updateNeighborStars(); } catch (eNS) { void eNS; }   // vox327: suns first, always
  const on = !!window._GALAXY_IMPOSTORS;
  _galaxyImpostors.visible = on;
  if (!on) return;
  if (_currentCellX === null || _currentCellZ === null) return;
  const groups = _galaxyImpostors.children;
  let idx = 0;
  for (let dx = -IMPOSTOR_RADIUS; dx <= IMPOSTOR_RADIUS; dx++) {
    for (let dz = -IMPOSTOR_RADIUS; dz <= IMPOSTOR_RADIUS; dz++) {
      const cellGroup = groups[idx++];
      if (!cellGroup) continue;
      if (dx === 0 && dz === 0) { cellGroup.visible = false; continue; }   // real system here
      const cx = _currentCellX + dx, cz = _currentCellZ + dz;
      const cell = _impostorStarForCell(cx, cz);
      cellGroup.visible = true;
      const star = cellGroup.children[0];
      star.position.set(cell.x, cell.y, cell.z);
      star.material.color.setHex(cell.type.color);
      star.scale.setScalar(cell.type.radius * 24);   // vox127: 10x dispersion (SYSTEM_CELL) needs ~10x sprite scale for equal apparent size; x24 total = the brighter look the user chose
      // ── Representative planet dots (separate seeded stream from generateSystem) ──
      // Stable per cell, but NOT a claim of exact planets. Offset the seed so the
      // dot stream is independent of the star-type draws.
      const drng = mulberry32((cellSeed(cx, cz) ^ 0x9E3779B9) >>> 0);
      const dotCount = 2 + Math.floor(drng() * (MAX_DOTS - 1));   // 2..MAX_DOTS
      const starR = cell.type.radius;
      for (let d = 0; d < MAX_DOTS; d++) {
        const dot = cellGroup.children[1 + d];
        if (!dot) continue;
        if (d >= dotCount || !window._IMPOSTOR_DOTS) { dot.visible = false; continue; }   // vox326: stars read as STARS; dots were the vox294 blob complaint
        // Orbit ring + angle, in the star's local frame (dot is child of group
        // but positioned in WORLD coords since the group is at origin).
        const ringT = (d + 0.5) / dotCount;
        const orbitR = starR * 2.4 + ringT * 5200;
        const ang = drng() * Math.PI * 2;
        const incl = (drng() - 0.5) * 0.5;
        dot.position.set(
          cell.x + Math.cos(ang) * orbitR,
          cell.y + Math.sin(ang) * orbitR * Math.sin(incl),
          cell.z + Math.sin(ang) * orbitR
        );
        // Small worlds: scale a fraction of the star, varied.
        dot.scale.setScalar(starR * (0.12 + drng() * 0.18));
        dot.visible = true;
      }
    }
  }
}
