          if (typeof showLoreWhisper === 'function') showLoreWhisper('\u25c9 ' + nm + ' \u2014 ' + tierName + ' scanned');
          if (k.tier === 5 && !k.discoveryChecked) { _revealDiscovery(agent.species, k); }
