  const w = window._foodWeb(); let s = w.species && Object.values(w.species).find(x => x.name === nm);
  if (!s && window._dragonSpecies && window._dragonSpecies.name === nm) s = window._dragonSpecies;   // vox319: drakes live outside the web
  if (!s) return null;
  const out = { name: nm, tier: k.tier, lines: [] };
  const b = s.body || {};
