    if (k.discovery) out.lines.push({ label: '\u2757 discovery', val: k.discovery });
    if (w.keystone && w.keystone.indexOf(nm) === 0) out.lines.push({ label: 'note', val: 'KEYSTONE species \u2014 removal would cascade' });
    if (w.symbiosis && w.symbiosis.indexOf(nm) >= 0) out.lines.push({ label: 'note', val: 'in a symbiosis \u2014 handle with care' });
