                var shard = new THREE.Mesh(new THREE.OctahedronGeometry(0.28, 0),
                    new THREE.MeshStandardMaterial({ color: 0x022, emissive: 0x01a982, emissiveIntensity: 1.2, roughness: 0.4 }));
