    let ctxLost = false;
    try { ctxLost = cockpitRenderer.getContext().isContextLost(); } catch (e) {}
    if (ctxLost) {
        if (!_bbVerdict) {
            _bbVerdict = true;
            try { console.error('[blackbox] VERDICT: WEBGL CONTEXT LOST -- genuine GPU death'); } catch (e) {}
            try { if (typeof showLoreWhisper === 'function') showLoreWhisper('\u25FC BLACK BOX VERDICT: GPU context LOST \u2014 genuine memory/driver death. Screenshot this.'); } catch (e) {}
        }
        return;
    }
    let lum = -1;
    try {
        if (!_bbRT) { _bbRT = new THREE.WebGLRenderTarget(8, 8); _bbBuf = new Uint8Array(256); }
        const prev = cockpitRenderer.getRenderTarget();
        cockpitRenderer.setRenderTarget(_bbRT);
        cockpitRenderer.render(cockpitScene, cockpitCamera);
        cockpitRenderer.readRenderTargetPixels(_bbRT, 0, 0, 8, 8, _bbBuf);
        cockpitRenderer.setRenderTarget(prev);
        let s = 0;
        for (let i = 0; i < 256; i += 4) s += _bbBuf[i] * 0.299 + _bbBuf[i + 1] * 0.587 + _bbBuf[i + 2] * 0.114;
        lum = s / 64;
    } catch (e) { lum = -2; }
    let mem = '';
    try { const m = cockpitRenderer.info.memory; mem = ' geo=' + m.geometries + ' tex=' + m.textures; } catch (e) {}
    try { console.log('[blackbox] lum=' + Math.round(lum) + ' ctx=alive' + mem + (_bbStage ? ' stage=' + _bbStage : '')); } catch (e) {}
    // Recovery detection: light returned after a bisection stage
    if (_bbStage > 0 && lum >= 8 && !_bbVerdict) {
        _bbVerdict = true;
        const culprit = _BB_STAGES[_bbStage - 1] || 'stage ' + _bbStage;
        try { if (_bbStage === 1) localStorage.setItem('l99_farshell_off', (typeof surfacePlanetType === 'string' && surfacePlanetType) ? surfacePlanetType : '1'); } catch (eBB) { void eBB; }   // da056: verdicts persist PER WORLD
        try { console.error('[blackbox] VERDICT: hiding "' + culprit + '" restored the light -- THAT is the blackout'); } catch (e) {}
        try { if (typeof showLoreWhisper === 'function') showLoreWhisper('\u25FC BLACK BOX VERDICT: hiding the ' + culprit.toUpperCase() + ' brought the world back. Screenshot this \u2014 that is the bug.'); } catch (e) {}
        return;
    }
