  const wy=(typeof SURF_WATER_Y==='number'?SURF_WATER_Y:0), deckY=wy+Math.max(5,towerH*0.10);
  const mat=new THREE.MeshStandardMaterial({color:colHex,roughness:0.5,metalness:0.2,emissive:colHex,emissiveIntensity:0.4});
