        const pier = new THREE.Mesh(new THREE.BoxGeometry(deckW * 0.13, Math.max(6, deckY - wy + 8), deckW * 0.13), girderMat);
        pier.position.set(cx + px * s * 0.72, wy + (deckY - wy) * 0.5 - 4, cz + pz * s * 0.72);
        pier.rotation.y = ang; g.add(pier);
