      // rest render terrain-only (the distance 'geography' shader). This moves
      // the whole flora budget up close where the player can actually see it.
      const _perfLow = P.perfLow;
      const _effNearView = _perfLow ? Math.min(FLORA_NEAR_VIEW, 1) : FLORA_NEAR_VIEW;
      // fix541: pull the TREELINE in to cut draw cost. The near full-clutter ring
      // (_effNearView) is untouched, so close-up / walking detail is unchanged --
      // only the far trees-only band shrinks. Tunable: window._FLORA_VIEW_MUL (1=full).
      const _fvMul = (typeof window._FLORA_VIEW_MUL === 'number') ? window._FLORA_VIEW_MUL : 0.66;
      let _effFloraView = _perfLow ? Math.min(FLORA_VIEW, 2)
                                   : Math.max(_effNearView, Math.round(FLORA_VIEW * _fvMul));
      // fix755: during the settle window pull the flora radius in to the near ring
      // and ramp it back out, so the first frames after touchdown don't over-build.
      // fix757: clamp to a genuinely TIGHT floor (1 chunk) ramping to full. fix755 clamped
      // toward _effNearView, which EQUALS the normal _effFloraView at default/LOW quality --
      // a no-op, which is why rocks still loaded wide. This floor is real (1 -> full).
      if (_settle < 1) {
        const _fMin = (typeof window._SETTLE_FLORA_MIN === 'number') ? window._SETTLE_FLORA_MIN : 1;
        _effFloraView = Math.max(_fMin, Math.round(_fMin + (_effFloraView - _fMin) * _settle));
      }
      const nearFlora = (Math.abs(dx) <= _effFloraView && Math.abs(dz) <= _effFloraView);
      // Two flora bands: full clutter (grass/flowers/stones + trees) within
      // the near ring, then trees-only treeline. Under recording/low-FPS load,
      // distant full-architecture trees are removed before they can dominate
      // the GPU; terrain remains, preserving the horizon and navigation.
