  const angular=P.q==='HIGH'?128:(P.perfLow?80:104),radial=P.q==='HIGH'?20:16,key=[cx,cz,Math.round(inner),Math.round(outer),angular,radial,surfaceSeed,surfacePlanetType].join(':');
