// ── BUILD-SURFACE DIAGNOSTIC OVERLAY ─────────────────────────────────────
// The buildSurface function has been throwing on user devices, and the
// console logs aren't always visible (filter set wrong, or popout context).
// This writes the latest checkpoint to a fixed-position overlay so the
// user can see exactly where buildSurface died without opening DevTools.
// Cleared automatically when buildSurface reaches CP-8 (complete).
function _bsLog(msg, isError) {
  console.log(isError ? '[buildSurface ERROR] ' + msg : msg);
  try {
    let el = document.getElementById('_bs-diag');
    if (!el) {
      el = document.createElement('div');
      el.id = '_bs-diag';
      el.style.cssText = 'position:fixed;top:8px;left:50%;transform:translateX(-50%);'
        + 'z-index:99999;padding:6px 12px;border-radius:6px;'
        + 'font-family:monospace;font-size:11px;letter-spacing:1px;'
        + 'background:rgba(0,0,0,0.85);color:#bdc73c;'
        + 'border:1px solid rgba(189,199,60,0.5);pointer-events:none;'
        + 'max-width:80vw;white-space:pre-wrap;';
      document.body.appendChild(el);
    }
    if (isError) {
      el.style.background = 'rgba(60,0,0,0.92)';
      el.style.color = '#ff8a8a';
      el.style.borderColor = 'rgba(255,107,107,0.7)';
    }
    el.textContent = msg;
  } catch(e) {}
}
function _bsClear() {
  try {
    const el = document.getElementById('_bs-diag');
    if (el && el.parentNode) el.parentNode.removeChild(el);
  } catch(e) {}
}


