// ── CRYSTAL shader ── faceted polyhedron with translucent interior
const SDF_FRAG_CRYSTAL = `
  precision mediump float;
  varying vec2 vUv;
  uniform float uTime;
  uniform float uHigh;
  uniform float uHue;
  uniform float uFacets;       // per-instance count
  uniform float uSpin;

  float sdOctahedron(vec3 p, float s) {
    p = abs(p);
    return (p.x + p.y + p.z - s) * 0.57735;
  }
  // SDF: rotated octahedron with audio-driven scale
  float sdCrystal(vec3 p) {
    float c = cos(uTime * uSpin);
    float s = sin(uTime * uSpin);
    p.xz = mat2(c, -s, s, c) * p.xz;
    float scale = 0.8 + uHigh * 0.12;
    float d = sdOctahedron(p, scale);
    // Add subdivision facets for higher uFacets — simulate
    // higher-frequency surface detail
    float ripple = sin(p.x * uFacets + uTime) * cos(p.y * uFacets) * 0.025;
    return d + ripple;
  }
  vec3 calcNormal(vec3 p) {
    vec2 e = vec2(0.001, 0.0);
    return normalize(vec3(
      sdCrystal(p + e.xyy) - sdCrystal(p - e.xyy),
      sdCrystal(p + e.yxy) - sdCrystal(p - e.yxy),
      sdCrystal(p + e.yyx) - sdCrystal(p - e.yyx)
    ));
  }
  vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1., 2./3., 1./3., 3.);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6. - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0., 1.), c.y);
  }
  void main() {
    vec2 uv = (vUv - 0.5) * 2.0;
    vec3 ro = vec3(0.0, 0.0, 2.0);
    vec3 rd = normalize(vec3(uv, -2.0));
    float t = 0.0;
    for (int i = 0; i < 32; i++) {
      vec3 p = ro + rd * t;
      float d = sdCrystal(p);
      if (d < 0.001) break;
      t += d;
      if (t > 5.0) { discard; }
    }
    vec3 p = ro + rd * t;
    vec3 n = calcNormal(p);
    vec3 lightDir = normalize(vec3(0.5, 0.9, 0.4));
    float diff = max(dot(n, lightDir), 0.0);
    float rim  = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
    // Crystals show a bright specular highlight
    vec3 R = reflect(rd, n);
    float spec = pow(max(dot(R, lightDir), 0.0), 32.0);
    vec3 baseCol = hsv2rgb(vec3(uHue, 0.55, 0.95));
    vec3 col = baseCol * (0.5 + diff * 0.4);
    col += spec * vec3(1.0, 1.0, 0.95) * 0.8;
    col += rim * baseCol * 0.7;
    gl_FragColor = vec4(col, 1.0);
  }
`;

// Quad geometry shared by all SDF creatures — built once
let _sdfQuadGeom = null;
function _getSdfQuad() {
  if (!_sdfQuadGeom) _sdfQuadGeom = new THREE.PlaneGeometry(1, 1);
  return _sdfQuadGeom;
}

// Build a single SDF creature mesh — returns a mesh ready to add to the scene.
// kind: 'sdf_orb' | 'sdf_tendril' | 'sdf_crystal'
// rand: PRNG fn for per-instance variation
function makeSDFCreature(kind, rand) {
  let frag, baseUniforms;
  if (kind === 'sdf_orb') {
    frag = SDF_FRAG_ORB;
    baseUniforms = {
      uTime:      { value: 0 },
      uBass:      { value: 0 },
      uHue:       { value: rand() },
      uPulseRate: { value: 1.4 + rand() * 1.6 },   // 1.4-3.0 — individual
      uBumpFreq:  { value: 3.0 + rand() * 4.0 }    // 3-7 — surface roughness
    };
  } else if (kind === 'sdf_tendril') {
    frag = SDF_FRAG_TENDRIL;
    baseUniforms = {
      uTime:       { value: 0 },
      uMid:        { value: 0 },
      uHue:        { value: rand() },
      uTentacles:  { value: 3 + Math.floor(rand() * 6) },   // 3-8
      uWaveSpeed:  { value: 1.2 + rand() * 1.8 },
      uIndividual: { value: rand() * 6.28 }
    };
  } else {  // sdf_crystal
    frag = SDF_FRAG_CRYSTAL;
    baseUniforms = {
      uTime:   { value: 0 },
      uHigh:   { value: 0 },
      uHue:    { value: rand() },
      uFacets: { value: 8 + rand() * 14 },    // 8-22 — facet density
      uSpin:   { value: 0.3 + rand() * 1.2 }
    };
  }
  const mat = new THREE.ShaderMaterial({
    uniforms: baseUniforms,
    vertexShader: SDF_VERTEX,
    fragmentShader: frag,
    transparent: true,
    side: THREE.DoubleSide
  });
  const mesh = new THREE.Mesh(_getSdfQuad(), mat);
  mesh.userData.sdfKind = kind;
  mesh.userData.sdfUniforms = baseUniforms;
  return mesh;
}


