window._reefTick = function(t, dt){
  const SW=window._reefSway;
  if (SW && SW.length){
    for (let i=SW.length-1;i>=0;i--){ const c=SW[i];
      if (!c.m || !c.m.parent){ SW.splice(i,1); continue; }
      c.m.rotation.z = Math.sin(t*c.sp + c.ph)*c.amp;
      c.m.rotation.x = Math.cos(t*c.sp*0.8 + c.ph)*c.amp*0.6;
    }
  }
  const S=window._reefShoals; if (!S || !S.length) return;
  for (let i=S.length-1;i>=0;i--){
    const sh=S[i];
    if (!sh.group || !sh.group.parent){ S.splice(i,1); continue; }
    const col=sh.water - sh.seabed, floorL=0.6, ceilL=Math.max(0.9, col-1.5), midL=(floorL+ceilL)*0.5;
    const sway=Math.min(1.2,(ceilL-floorL)*0.4);
    for (let j=0;j<sh.fish.length;j++){
      const fi=sh.fish[j], ang=t*fi.sp + fi.ph;
      const px=Math.cos(ang)*fi.rad, pz=Math.sin(ang*0.9+fi.yr)*fi.rad;
      fi.feed += dt*fi.frate; const feeding=(fi.feed%1)>0.6;
      const yL = feeding ? floorL+0.3 : Math.min(ceilL, Math.max(floorL, midL + Math.sin(ang*1.7)*sway));
      fi.m.position.set(px, yL, pz);
      fi.m.rotation.y = -ang + Math.PI;
      fi.m.rotation.z = feeding ? -0.5 : Math.sin(ang*2)*0.12;
    }
  }
};
// Locator: spiral-search outward from the camera for the nearest reef-depth water and
// report its distance + bearing. Call window._findReef() from the console (or the SCAN-area
// world). Read-only — never mutates flight state.
window._findReef = function(maxR){
  maxR = maxR || 5000;
  var cam = (typeof cockpitCamera!=='undefined' && cockpitCamera) ? cockpitCamera : null;
  var cx = cam ? cam.position.x : 0, cz = cam ? cam.position.z : 0;
  var best=null, bestD=Infinity, lim=(window._REEF_DEPTH||40);
  for (var r=40; r<=maxR && !best; r+=40){
    for (var a=0; a<360; a+=10){
      var rad=a*Math.PI/180, wx=cx+Math.cos(rad)*r, wz=cz+Math.sin(rad)*r, gy;
      try{ gy=surfaceHeightAt(wx,wz,surfaceSeed,surfacePlanetType); }catch(e){ continue; }
      var d=SURF_WATER_Y-gy;
      if (d>0.3 && d<lim){ var dist=Math.hypot(wx-cx,wz-cz); if (dist<bestD){ bestD=dist; best={x:wx,z:wz,depth:d}; } }
    }
  }
  if (!best){ var nm='No reef-depth water within '+maxR+'m of you.'; try{showLoreWhisper(nm);}catch(e){} console.log('[reef] '+nm); return null; }
  var bearing=(Math.atan2(best.z-cz,best.x-cx)*180/Math.PI+360)%360;
  var msg='Reef '+Math.round(bestD)+'m out, bearing '+Math.round(bearing)+'\u00b0, '+best.depth.toFixed(1)+'m deep.';
  try{showLoreWhisper(msg);}catch(e){}
  console.log('[reef] '+msg, best);
  return best;
};
// Locator: nearest cave mouth from the camera. Caves only render in voxel in-chunk mode, so
// this requires that toggle. Read-only — probes the cave SDF, never mutates state.
window._findCave = function(maxR){
  maxR = maxR || 3500;
  if (window._VOX_INCHUNK !== true){ var w0='Turn voxel terrain ON first — caves only carve in voxel mode.'; try{showLoreWhisper(w0);}catch(e){} console.log('[cave] '+w0); return null; }
  if (typeof window._vCaveProbe !== 'function'){ console.log('[cave] probe unavailable'); return null; }
  var cam=(typeof cockpitCamera!=='undefined' && cockpitCamera)?cockpitCamera:null;
  var cx=cam?cam.position.x:0, cz=cam?cam.position.z:0, best=null, bestD=Infinity;
  for (var r=30; r<=maxR && !best; r+=30){
    for (var a=0; a<360; a+=8){
      var rad=a*Math.PI/180, wx=cx+Math.cos(rad)*r, wz=cz+Math.sin(rad)*r, h;
      try{ h=surfaceHeightAt(wx,wz,surfaceSeed,surfacePlanetType); }catch(e){ continue; }
      var open=false;
      for (var d=2; d<=16; d+=3.5){ if (window._vCaveProbe(wx,h-d,wz)>0){ open=true; break; } }
      if (open){ var dist=Math.hypot(wx-cx,wz-cz); if (dist<bestD){ bestD=dist; best={x:wx,z:wz,surf:h}; } }
    }
  }
  if (!best){ var nm='No cave opening within '+maxR+'m. Move on — caves carve in the chunks nearest you.'; try{showLoreWhisper(nm);}catch(e){} console.log('[cave] '+nm); return null; }
  var bearing=(Math.atan2(best.z-cz,best.x-cx)*180/Math.PI+360)%360;
  var msg='Cave mouth '+Math.round(bestD)+'m out, bearing '+Math.round(bearing)+'\u00b0.';
  try{showLoreWhisper(msg);}catch(e){}
  console.log('[cave] '+msg, best);
  return best;
};
