  if(!group||!withFlora||(surfacePlanetType!=='TERRAN'&&surfacePlanetType!=='MYSTICAL'))return;
  const ox=cx*CHUNK_SIZE,oz=cz*CHUNK_SIZE,minX=ox-CHUNK_SIZE*.5,maxX=ox+CHUNK_SIZE*.5,minZ=oz-CHUNK_SIZE*.5,maxZ=oz+CHUNK_SIZE*.5;
  const net=_ensureWatershedNetwork();const rand=_inlandRand(((cx*73856093)^(cz*19349663)^((surfaceSeed*10000)|0))>>>0);
  for(const lake of net.lakes){if(lake.x>=minX&&lake.x<maxX&&lake.z>=minZ&&lake.z<maxZ&&lake.y>SURF_WATER_Y+1)group.add(_lakeMesh(lake.x,lake.z,lake.y,lake.r,ox,oz,rand));}
