  for(const [tx,tz] of towers){_mysticalMesh(g,new THREE.CylinderGeometry(15,18,76,10),M.stone,tx,38,tz);_mysticalMesh(g,new THREE.ConeGeometry(22,30,10),M.roof,tx,91,tz);for(let i=0;i<8;i++){const a=i*Math.PI/4;_mysticalMesh(g,new THREE.BoxGeometry(5,7,5),M.stone,tx+Math.cos(a)*14,78,tz+Math.sin(a)*14);}}
