  if (planetType === 'GAS') return;

  // Decide which species this planet has — variety per seed
  const hasGrazers  = rand() > 0.2;
  const hasHoppers  = rand() > 0.3;
  const hasFloaters = rand() > 0.4;
  const hasBirds    = rand() > 0.3;
  const hasFish     = (planetType === 'OCEAN' || planetType === 'TERRAN') && rand() > 0.3;

  // Helper to spawn a herd: multiple instances near a center point
  // fix309: DINO SPECIES BANK — 40 species of the late Cretaceous, classed:
  // H herbivore (future GROUND MOUNTS), C carnivore (future PACK HUNTERS),
  // F flyer (future FLYING MOUNTS), M marine. Herds on primal worlds are
  // assigned a species matching their behavioral archetype; this is the data
  // layer that riding, flying, hunting and pack mechanics build on next.
