    const _SPAN = window._surfPrimal ? 1500 : 900;
    const _herdSpecies = window._surfPrimal ? _dinoSpecies(kind) : null;
    // fix327 stage E: a third of carnivore herds are SCAVENGERS — they never
    // hunt the living, only converge on carcasses to clear them.
    if (_herdSpecies && _herdSpecies.cls === 'C' && rand() < 0.3) _herdSpecies.scav = true;
    // Pick a "spawn center" for the herd — they'll cluster around this.
    // fix328: HABITAT ZONING (primal worlds) — pick the center that best
    // fits the species: marine/wading near water, armoured & ceratopsians on
    // open plains, sauropods near tree-height ground, others anywhere. Sample
    // a handful of candidate centers and keep the best-fitting one.
