      const N2 = (_herdSpecies.name || '').toUpperCase();
      const wantWater = (kind === 'fish') || /SPINOSAURUS|BARYONYX|MOSASAURUS|ELASMOSAURUS|MAIASAURA/.test(N2);
      const wantPlain = /TRICERATOPS|TOROSAURUS|ANKYLOSAURUS|EUOPLOCEPHALUS|EDMONTOSAURUS|STYRACOSAURUS/.test(N2);
      let bestScore = -1e9;
