  if (hasFloaters || _pw) spawnHerd('floater', (5 + Math.floor(rand()*6)) * _pmC,  _makeFloaterGeom, [1.5 * _pmS, 3.5 * _pmS], r => 14 + r()*120, [0.45, 0.7]);
  if (hasBirds || _pw)    spawnHerd('bird',    (8 + Math.floor(rand()*12)) * _pmC, _makeBirdGeom,    [1.0 * _pmS, 2.2 * _pmS], r => 30 + r()*200, [0.0, 1.0]);
  if (hasFish)     spawnHerd('fish',    14 + Math.floor(rand()*14), _makeFishGeom,    [1.0, 2.0], r => -35 - r()*95, [0.45, 0.7]);

  // ── DUCKS ──────────────────────────────────────────────────────────────
