      const cx = (rand() - 0.5) * 1600;
      const cz = (rand() - 0.5) * 1600;
      const terrainY = surfaceHeightAt(cx, cz, seed, planetType);
      // Shallow-water test: terrain must be below water surface by 1 to 25u
      // (deep enough to be visibly underwater, shallow enough to be a pond
      // rather than open ocean).
