          phase: rand() * Math.PI * 2,
          wanderAngle: rand() * Math.PI * 2,
          wanderTimer: rand() * 3,
          heightOffset: 0,
          velX: 0, velZ: 0,
          startleT: 0,
          // Constrain to original pond — ducks shouldn't wander onto land
