  for (let i = 0; i < puffs.length; i++) { d.position.set(0, -9999, 0); d.updateMatrix(); inst.setMatrixAt(i, d.matrix); }
  inst.instanceMatrix.needsUpdate = true;
  const grp = new THREE.Group(); grp.userData.isCityHalo = true; grp.add(inst); surfaceObjects.add(grp);
