        plain(0x2a4a44, -W * 0.3, 0.74, -D * 0.28 - 0.4, 1.9, 0.14, 0.4);
        plain(0x8a8f96, W * 0.28, 0.5, -D * 0.5 + 0.5, W * 0.35, 1.0, 0.9);            // galley strip
