        for (let cr2 = 0; cr2 < 6 + Math.floor(rnd() * 6); cr2++) {
            const tip = rnd() < 0.4;
            const crm = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.7, 0.8),
                new THREE.MeshLambertMaterial({ color: 0x3a3f46 }));
            crm.position.set(cx + (rnd() - 0.5) * W * 0.75, cy + (tip ? 0.28 : 0.35), cz + (rnd() - 0.5) * D * 0.7);
            if (tip) crm.rotation.z = 0.5 + rnd() * 0.6;
            crm.rotation.y = rnd() * Math.PI;
            g.add(crm);
        }
        plain(0x14161c, 0, 1.1, -D * 0.5 + 0.3, 2.4, 1.2, 0.14, 0x2a1416, 0.35);   // dead console
        plain(0x22262c, 0, 0.4, -D * 0.5 + 0.5, 2.8, 0.8, 0.5);
