            plain(0x1a1c20, -W * 0.3 + pp2 * W * 0.3, H - 0.7, (rnd() - 0.5) * D * 0.4, 0.06, 1.4, 0.06);
        const em = new THREE.PointLight(0xff3826, 2.4, Math.max(W, D) * 1.3);
        em.position.set(cx, cy + H - 0.5, cz);
