  const haloMat = new THREE.MeshBasicMaterial({ color: 0xffe090, fog: false, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending });
  const moonMat = new THREE.MeshBasicMaterial({ color: 0xd8e8ff, fog: false, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending });
  const sunSph  = new THREE.Mesh(new THREE.SphereGeometry(65, 14, 9),  sunMat);
  const haloSph = new THREE.Mesh(new THREE.SphereGeometry(140, 12, 8), haloMat);
  const moonSph = new THREE.Mesh(new THREE.SphereGeometry(40, 12, 8),  moonMat);
  sunSph.frustumCulled = haloSph.frustumCulled = moonSph.frustumCulled = false;
  const grp = new THREE.Group(); grp.userData.isCityHalo = true;
  grp.add(sunSph); grp.add(haloSph); grp.add(moonSph); surfaceObjects.add(grp);
  if (!window._cityHalos) window._cityHalos = []; window._cityHalos.push(grp);
  window._sunMesh = sunSph; window._sunMat = sunMat;
