    dummy.rotation.set(0, rotY, 0); dummy.scale.set(bw * (kind === 'pickup' ? 0.82 : 0.88), ch2, cl); dummy.updateMatrix();
    cabMats.push(dummy.matrix.clone());
    dummy.position.set(vx + Math.sin(rotY) * cOffZ, gy + bhh + ch2 * 0.62 + 0.3, vz + Math.cos(rotY) * cOffZ);
    dummy.rotation.set(0, rotY, 0); dummy.scale.set(bw * 0.72, ch2 * 0.58, cl * 0.82); dummy.updateMatrix();
