            const pg = g.createRadialGradient(px, py, pr * 0.15, px, py, pr);
            pg.addColorStop(0, rng() < 0.5 ? 'rgba(45,40,35,0.22)' : 'rgba(225,218,206,0.18)');
            pg.addColorStop(1, 'rgba(0,0,0,0)');
