        if (typeof throttlePct === 'number') throttlePct = Math.min(throttlePct, _apPow);
        if (typeof cockpitThrottle === 'number') cockpitThrottle = _apPow * 4.0;   // da069: same scale, no idle offset
        // da062: THE VECTOR SURVIVES. Zeroing shipVel froze the world for
        // the lerp-up out of the handoff -- a visible hitch at the exact
