      const _alwaysBoost = (window._ALWAYS_BOOST !== false);
      const _boostInput = (_manualBoost || _alwaysBoost) && !_inCave;   // fix794: no boost while cave-diving
      // ── HYPER-BOOST RAMP ──────────────────────────────────────────────────
