      const sliderCruiseTarget = throttlePct > 0 ? (THROTTLE_MIN_PCT + throttlePct * (1 - THROTTLE_MIN_PCT)) * CRUISE_MAX : 0;
      const cruiseTarget = _autoFlightState().on ? Math.max(sliderCruiseTarget, speed * 8.0) : sliderCruiseTarget;
