          for (const c7 of el.children) { const s7 = (c7.textContent || '').trim(); if (s7) { t7 = s7.split('\n')[0].slice(0, 26).toUpperCase(); break; } }
          if (!t7) t7 = 'MORE';
          if (!SS.sub[t7]) { SS.sub[t7] = _mkSection(t7, false); panel.appendChild(SS.sub[t7]); }
