    root.FlightCivic.decodeKay = decodeKay;
    root.FlightCivic.assemblePerson = assemblePerson;

    // ---- the builder -------------------------------------------------------
    // Given a scene and a flat-ground sampler, lay a settlement out by the laws
    // and stand villagers on its streets.
    root.FlightCivic.build = function (scene, opts) {
        if (root._FLIGHT_CIVIC === false) return null;
        opts = opts || {};
        var seed = opts.seed == null ? 1337 : opts.seed;
        var cx = opts.x || 0, cz = opts.z || 0;
        var scale = opts.scale || 1;
        var groundAt = opts.groundAt || function () { return 0; };
        var terrain = { sea: opts.sea == null ? -1e9 : opts.sea, heightAt: groundAt };

        var seeds = CivicLaws.seedsNear(cx, cz, seed, opts.rings == null ? 2 : opts.rings, terrain);
        if (!seeds.length) return null;
        seeds.sort(function (a, b) {
            return Math.hypot(a.x - cx, a.z - cz) - Math.hypot(b.x - cx, b.z - cz);
        });
        seeds[0].rank = 1;                       // the one you were sent to see
        seeds = CivicLaws.keepLaw(seeds);
        var lay = CivicLaws.layout(seeds[0], seeds, seed, terrain);
        if (!lay) return null;

        var G = new THREE.Group();
        G.userData.civic = true;
        G.scale.setScalar(scale);

        // streets: one flat ribbon per segment, laid on the ground
        var roadMat = new THREE.MeshStandardMaterial({
            color: 0x1a1a20, roughness: 0.95, metalness: 0.0
        });
        var si;
        for (si = 0; si < lay.streets.length; si++) {
            var st = lay.streets[si];
            var dx = st.b[0] - st.a[0], dz = st.b[1] - st.a[1];
            var L = Math.hypot(dx, dz);
            if (L < 0.5) continue;
            var road = new THREE.Mesh(new THREE.PlaneGeometry(st.w, L), roadMat);
            road.rotation.x = -Math.PI / 2;
            road.rotation.z = -Math.atan2(dx, dz);
            road.position.set(st.a[0] + dx * 0.5 - cx,
                              groundAt(st.a[0] + dx * 0.5, st.a[1] + dz * 0.5) + 0.05,
                              st.a[1] + dz * 0.5 - cz);
            G.add(road);
        }

        // buildings: core to edge, so the skyline has a middle
        var bodyGeo = new THREE.BoxGeometry(1, 1, 1);
        var winTex = paintWindows();
        var towerMat = new THREE.MeshStandardMaterial({
            color: 0x14161c, roughness: 0.55, metalness: 0.25,
            emissiveMap: winTex, emissive: new THREE.Color(0xffffff), emissiveIntensity: 1.0
        });
        var pi, put = 0;
        for (pi = 0; pi < lay.parcels.length; pi++) {
            var p = lay.parcels[pi];
            var hgt = p.kind === 'tower' ? (40 + CivicLaws.h3(pi, 7, seed) * 96)
                    : p.kind === 'midrise' ? (9 + CivicLaws.h3(pi, 11, seed) * 16)
                    : (4 + CivicLaws.h3(pi, 13, seed) * 4);
            var b = new THREE.Mesh(bodyGeo, towerMat);
            b.scale.set(p.w, hgt, p.d);
            b.position.set(p.x - cx, groundAt(p.x, p.z) + hgt * 0.5, p.z - cz);
            b.rotation.y = p.ry || 0;
            G.add(b);
            put++;
        }
        G.userData.buildings = put;

        // the people, on the streets the laws just drew
        var wanted = opts.people == null
            ? (lay.rank === 1 ? 36 : lay.rank === 2 ? 16 : 9)
            : opts.people;
        var made = 0, tries = 0, folk = [];
        var kit = decodeKay();
        if (kit && lay.streets.length) {
            while (made < wanted && tries < wanted * 12) {
                tries++;
                var s2 = lay.streets[Math.floor(CivicLaws.h3(tries, 3, seed) * lay.streets.length) % lay.streets.length];
                var t2 = CivicLaws.h3(tries, 5, seed);
                var px = s2.a[0] + (s2.b[0] - s2.a[0]) * t2;
                var pz = s2.a[1] + (s2.b[1] - s2.a[1]) * t2;
                var side = (CivicLaws.h3(tries, 9, seed) < 0.5 ? -1 : 1) * (s2.w * 0.5 + 1.2);
                var ang = Math.atan2(s2.b[0] - s2.a[0], s2.b[1] - s2.a[1]);
                px += Math.cos(ang) * side; pz -= Math.sin(ang) * side;
                var person = null;
                try { person = assemblePerson(made + seed, kit); } catch (eP) { break; }
                if (!person || !person.group) break;
                person.group.position.set(px - cx, groundAt(px, pz), pz - cz);
                person.group.rotation.y = ang + (CivicLaws.h3(tries, 17, seed) < 0.5 ? 0 : Math.PI);
                G.add(person.group);
                root.L99Life133.fitPerson(THREE,person.group,made+seed,'flight',2.3);
                folk.push(person);
                made++;
            }
        }
        G.userData.people = made;

        if (scene) scene.add(G);
        var handle = { group: G, layout: lay, people: folk, buildings: put };
        root._civicLive = root._civicLive || [];
        root._civicLive.push(handle);
        handle.dispose = function () {
            if (scene) { try { scene.remove(G); } catch (e) {} }
            var ix = root._civicLive.indexOf(handle);
            if (ix >= 0) root._civicLive.splice(ix, 1);   /* stop ticking a dead city */
        };
        return handle;
    };

    function paintWindows() {
        var cv = document.createElement('canvas');
        cv.width = 64; cv.height = 128;
        var x = cv.getContext('2d');
        x.fillStyle = '#07070c'; x.fillRect(0, 0, 64, 128);
        var r, c2;
        for (r = 4; r < 128; r += 8) {
            for (c2 = 4; c2 < 64; c2 += 8) {
                var lit = CivicLaws.h3(r, c2, 5);
                if (lit < 0.42) continue;
                x.fillStyle = lit > 0.86 ? '#ffd8a0' : (lit > 0.62 ? '#cfe4ff' : '#8fa8c8');
                x.fillRect(c2, r, 4, 5);
            }
        }
        var t = new THREE.CanvasTexture(cv);
        t.wrapS = t.wrapT = THREE.RepeatWrapping;
        return t;
    }

    // advance every villager's walk cycle; call from the flight frame loop
    root.FlightCivic.tick = function (handle, dt) {
        if (!handle || !handle.people) return;
        var i;
        for (i = 0; i < handle.people.length; i++) {
            var pp = handle.people[i];
            if (pp && pp.mixer) { try { pp.mixer.update(dt); } catch (e) {} }
        }
    };
